import com.aveycole.agentlooper.*;
import java.util.*;
import java.io.*;
public final class EngineTest {
    static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    static float[] tone(int frames,double frequency,float gain){float[] a=new float[frames*2];for(int i=0;i<frames;i++)a[i*2]=a[i*2+1]=(float)(gain*Math.sin(2*Math.PI*frequency*i/LoopEngine.RATE));return a;}
    static void step(LoopEngine e,int frames,float value){float[] in=new float[frames*2],out=new float[frames*2];Arrays.fill(in,value);e.process(in,2,0,1,out,frames);}
    static void run(String n,Runnable r){r.run();System.out.println("PASS "+n);}
    public static void main(String[] args)throws Exception{
        run("unity capture and playback",()->{LoopEngine e=new LoopEngine();e.begin(0,false);step(e,48000,.2f);e.finish(0,false);LoopEngine.Layer l=e.banks[0].layers.get(0);check(l.audio.length==96000,"take length");for(float f:l.audio)check(f==.2f,"capture level");float[] out=new float[96000];e.process(null,2,0,1,out,48000);for(int i=8192;i<out.length;i++)check(Math.abs(out[i]-.2)<.000001,"playback level at "+i+": "+out[i]);});
        run("automatic overdub exact across 257-frame blocks",()->{LoopEngine e=new LoopEngine();e.bpm=300;e.banks[0].sync=e.banks[0].auto=true;e.begin(0,false);int period=e.measure();for(int i=0;i<(period*3+513)/257;i++)step(e,257,.15f);check(e.banks[0].layers.size()==3,"three completed passes");for(int i=0;i<3;i++){LoopEngine.Layer l=e.banks[0].layers.get(i);check(l.offset==(long)i*period,"exact origin");check(l.audio.length==period*2,"exact period");for(float f:l.audio)check(f==.15f,"no self-summing");}e.finish(0,false);check(!e.banks[0].recording,"explicit stop");});
        run("count-in excluded; click excluded from internal A bus",()->{LoopEngine e=new LoopEngine();e.bpm=300;e.countIn=1;e.click=true;e.banks[0].sync=true;e.begin(0,false);int period=e.measure();step(e,period,.5f);check(e.banks[0].layers.isEmpty(),"count-in");step(e,period,.2f);LoopEngine.Layer l=e.banks[0].layers.get(0);for(float f:l.audio)check(f==.2f,"cue excluded");e.countIn=0;e.banks[1].inputMode=1;e.banks[1].sync=true;e.begin(1,false);step(e,period,.9f);float[] a=e.banks[1].layers.get(0).audio;for(int i=8192;i<a.length;i++)check(Math.abs(a[i]-.2f)<.000001,"clean internal bus");});
        run("B measure-overdub follows A real off-grid restart",()->{LoopEngine e=new LoopEngine();LoopEngine.Bank a=e.banks[0],b=e.banks[1];a.layers.add(new LoopEngine.Layer(tone(70001,220,.1f),"A",1234));a.origin=1234;a.frame=21234;b.layers.add(new LoopEngine.Layer(tone(11000,220,.1f),"B",0));b.quantize=1;e.begin(1,true);check(b.armedAt==50001,"target actual A boundary");step(e,50001,.2f);check(b.waiting,"boundary not reached");step(e,11000,.3f);check(b.layers.size()==2,"overdub completed");check(b.layers.get(1).audio[0]==.3f,"exact first sample");});
        run("independent pitch/stretch and finite stereo",()->{LoopEngine e=new LoopEngine();LoopEngine.Layer l=new LoopEngine.Layer(tone(48000,220,.3f),"Tone",0);l.pitch=12;l.stretch=1.5;e.banks[0].layers.add(l);check(l.frames()==72000,"stretch duration");float[] out=new float[96000*2];long start=System.nanoTime();e.process(null,2,0,1,out,96000);int crossings=0;for(int i=24001;i<48000;i++)if(out[(i-1)*2]<=0&&out[i*2]>0)crossings++;check(Math.abs(crossings*2-440)<35,"pitch independent: "+crossings*2);for(int i=0;i<out.length;i+=2)check(Float.isFinite(out[i])&&out[i]==out[i+1],"finite coherent stereo");System.out.println("  2 seconds processed in "+((System.nanoTime()-start)/1000000)+" ms");});
        run("stretch preserves source pitch",()->{LoopEngine e=new LoopEngine();LoopEngine.Layer l=new LoopEngine.Layer(tone(48000,440,.3f),"Tone",0);l.stretch=1.5;e.banks[0].layers.add(l);float[] out=new float[96000];e.process(null,2,0,1,out,48000);int crossings=0;for(int i=12001;i<36000;i++)if(out[(i-1)*2]<=0&&out[i*2]>0)crossings++;check(Math.abs(crossings*2-440)<35,"stretch pitch: "+crossings*2);});
        run("Repitch couples duration and pitch",()->{LoopEngine e=new LoopEngine();LoopEngine.Layer l=new LoopEngine.Layer(tone(48000,220,.3f),"Tape",0);l.mode=1;l.pitch=12;e.banks[0].layers.add(l);check(l.frames()==24000,"tape duration");float[] out=new float[96000];e.process(null,2,0,1,out,48000);int crossings=0;for(int i=12001;i<36000;i++)if(out[(i-1)*2]<=0&&out[i*2]>0)crossings++;check(Math.abs(crossings*2-440)<10,"tape frequency");});
        run("filter responds during playback; independent layers",()->{LoopEngine e=new LoopEngine();LoopEngine.Layer l=new LoopEngine.Layer(tone(48000,8000,.3f),"Tone",0);e.banks[0].layers.add(l);float[] a=new float[48000],b=new float[48000];e.process(null,2,0,1,a,24000);l.cutoff=100;e.process(null,2,0,1,b,24000);double x=0,y=0;for(int i=4096;i<a.length;i++){x+=a[i]*a[i];y+=b[i]*b[i];}check(y<x*.01,"live cutoff");l.start=100;l.end=10100;check(l.frames()==10000,"trim");check(l.audio.length==96000,"nondestructive");});
        run("Wait for Input detects exact sample and ignores noise",()->{LoopEngine e=new LoopEngine();LoopEngine.Bank b=e.banks[0];b.waitInput=true;e.begin(0,false);step(e,128,.001f);check(b.signalArmed&&b.layers.isEmpty(),"noise ignored");float[] signal=new float[1024],out=new float[1024];for(int i=300;i<512;i++)signal[i*2]=signal[i*2+1]=.2f;e.process(signal,2,0,1,out,512);check(!b.signalArmed&&b.armedAt==428,"exact onset");step(e,480,.2f);e.finish(0,false);LoopEngine.Layer l=b.layers.get(0);check(l.offset==428&&l.audio.length==1384,"no silent lead-in");for(float f:l.audio)check(f==.2f,"unity onset");});
        run("Wait input respects count-in, quantization, cancellation and Auto OD",()->{LoopEngine e=new LoopEngine();LoopEngine.Bank a=e.banks[0],b=e.banks[1];a.layers.add(new LoopEngine.Layer(tone(1000,220,.1f),"A",0));a.frame=700;b.quantize=2;b.waitInput=true;e.begin(1,false);float[] signal=new float[1000],out=new float[1000];signal[800]=signal[801]=.2f;e.process(signal,2,0,1,out,500);check(b.armedAt==1300&&b.waiting,"next boundary after onset");e.finish(1,false);check(b.layers.isEmpty(),"cancel empty take");LoopEngine c=new LoopEngine();c.banks[0].waitInput=true;c.banks[0].auto=true;c.begin(0,false);step(c,100,.001f);c.finish(0,true);check(!c.banks[0].recording&&c.banks[0].layers.isEmpty(),"cancel without auto rearm");LoopEngine d=new LoopEngine();d.bpm=300;d.banks[0].sync=d.banks[0].auto=d.banks[0].waitInput=true;d.begin(0,false);step(d,10,0);step(d,d.measure()*2,.2f);check(d.banks[0].layers.size()==2&&!d.banks[0].signalArmed&&d.banks[0].recording,"continuous passes after trigger");LoopEngine f=new LoopEngine();f.countIn=1;f.banks[0].waitInput=true;f.begin(0,false);step(f,10,0);step(f,1,.2f);check(f.banks[0].armedAt==10+f.measure()&&f.banks[0].waiting,"count-in after trigger");});
        run("Warp aligns layers at next restart and preserves pitch/settings",()->{LoopEngine e=new LoopEngine();LoopEngine.Bank b=e.banks[0];LoopEngine.Layer a=new LoopEngine.Layer(tone(48000,220,.1f),"A",0),l=new LoopEngine.Layer(tone(96000,330,.2f),"B",1234);a.mute=true;l.pitch=-7;l.stretch=2;l.mode=1;b.layers.add(a);b.layers.add(l);b.frame=12000;e.toggleWarp(0);check(b.warpPending&&!b.warp,"warp queued");step(e,36000,0);check(!b.warp,"not before boundary");step(e,1,0);check(b.warp&&!b.warpPending&&b.cycle()==48000,"shared cycle");check(l.pitch==-7&&l.stretch==2&&l.mode==1&&l.offset==1234,"original settings preserved");float[] out=new float[96000];e.process(null,2,0,1,out,48000);int crossings=0;for(int i=12001;i<36000;i++)if(out[(i-1)*2]<=0&&out[i*2]>0)crossings++;check(Math.abs(crossings*2-220)<35,"locked independent pitch: "+crossings*2);l.end=48000;check(b.cycle()==48000,"trim cannot desync locked cycle");try{ByteArrayOutputStream wav=new ByteArrayOutputStream();AudioFiles.export(AudioFiles.snapshot(e,0),wav);check(AudioFiles.readWav(new ByteArrayInputStream(wav.toByteArray())).length==96000,"export one shared cycle");}catch(IOException ex){throw new RuntimeException(ex);}e.toggleWarp(0);check(!b.warp&&l.pitch==-7&&l.stretch==2,"unlock restores settings");});
        LoopEngine e=new LoopEngine();LoopEngine.Layer l=new LoopEngine.Layer(tone(48000,440,.2f),"Saved",411);l.start=100;l.end=20100;l.pitch=3;l.stretch=1.25;l.reverse=true;e.banks[1].layers.add(l);ByteArrayOutputStream data=new ByteArrayOutputStream();e.save(data);LoopEngine restored=new LoopEngine();restored.load(new ByteArrayInputStream(data.toByteArray()));LoopEngine.Layer n=restored.banks[1].layers.get(0);check(n.start==100&&n.end==20100&&n.pitch==3&&n.reverse&&Arrays.equals(l.audio,n.audio),"session exact");System.out.println("PASS lossless session round-trip");
        ByteArrayOutputStream wav=new ByteArrayOutputStream();AudioFiles.export(AudioFiles.snapshot(e,1),wav);float[] imported=AudioFiles.readWav(new ByteArrayInputStream(wav.toByteArray()));check(imported.length==50000,"float export length");for(float f:imported)check(Float.isFinite(f),"WAV finite");System.out.println("PASS float WAV export/import");
        System.out.println("ALL CHECKS PASSED");
    }
}
